<?php
declare(strict_types=1);require_once __DIR__.'/_funcoes.php';exigir_permissao('resumo.visualizar');
$ano=max(2020,min(2100,(int)($_GET['ano']??$_POST['ano']??date('Y'))));$mes=max(1,min(12,(int)($_GET['mes']??$_POST['mes']??date('n'))));$erro='';
$s=$pdo->prepare('SELECT * FROM ponto_competencias WHERE ano=:ano AND mes=:mes');$s->execute([':ano'=>$ano,':mes'=>$mes]);$competencia=$s->fetch()?:['ano'=>$ano,'mes'=>$mes,'situacao'=>'aberta'];
if($_SERVER['REQUEST_METHOD']==='POST'){exigir_permissao('ponto.editar');validar_csrf();try{$acao=trim($_POST['acao']??'');$just=trim($_POST['justificativa']??'');if(!in_array($acao,['fechar','reabrir'],true))throw new RuntimeException('Ação inválida.');if($acao==='reabrir'&&$just==='')throw new RuntimeException('A reabertura exige justificativa.');$antes=$competencia;$usuario=ponto_admin_nome();
if($acao==='fechar'){if(($competencia['situacao']??'aberta')==='fechada')throw new RuntimeException('A competência já está fechada.');$sql="INSERT INTO ponto_competencias (ano,mes,situacao,fechado_em,fechado_por) VALUES (:ano,:mes,'fechada',NOW(),:usuario) ON DUPLICATE KEY UPDATE situacao='fechada',fechado_em=NOW(),fechado_por=VALUES(fechado_por),reaberto_em=NULL,reaberto_por=NULL,justificativa_reabertura=NULL";$pdo->prepare($sql)->execute([':ano'=>$ano,':mes'=>$mes,':usuario'=>$usuario]);}
else{if(($competencia['situacao']??'aberta')!=='fechada')throw new RuntimeException('A competência já está aberta.');$pdo->prepare("UPDATE ponto_competencias SET situacao='aberta',reaberto_em=NOW(),reaberto_por=:usuario,justificativa_reabertura=:just WHERE ano=:ano AND mes=:mes")->execute([':usuario'=>$usuario,':just'=>$just,':ano'=>$ano,':mes'=>$mes]);}
$s->execute([':ano'=>$ano,':mes'=>$mes]);$depois=$s->fetch()?:[];ponto_historico($pdo,'ponto_competencias',(int)($depois['id']??0),$acao==='fechar'?'fechamento':'reabertura',$antes,$depois,$just?:null);registrar_auditoria('ponto',$acao==='fechar'?'competencia_fechada':'competencia_reaberta','ponto_competencias',(int)($depois['id']??0),$antes,$depois,'sucesso',null,$just?:null);redirect("competencias.php?ano={$ano}&mes={$mes}&salvo=1");}catch(Throwable $e){$erro=ponto_mensagem_erro($e);}}
$s->execute([':ano'=>$ano,':mes'=>$mes]);$competencia=$s->fetch()?:['ano'=>$ano,'mes'=>$mes,'situacao'=>'aberta'];$q=$pdo->prepare('SELECT COUNT(*) FROM pontos_trabalho WHERE YEAR(data)=:ano AND MONTH(data)=:mes');$q->execute([':ano'=>$ano,':mes'=>$mes]);$total=(int)$q->fetchColumn();$fechada=$competencia['situacao']==='fechada';
?>
